package cn.blockforge.generated.generatedmod.divinesurvey;
import cn.blockforge.generated.generatedmod.GeneratedMod;import cn.blockforge.generated.generatedmod.Network;import cn.blockforge.generated.generatedmod.progression.*;
import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.tags.TagKey;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.chunk.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.network.chat.Component;
import net.minecraftforge.event.TickEvent;import net.minecraftforge.event.entity.player.PlayerEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.network.PacketDistributor;
import java.util.*;import java.util.concurrent.CompletableFuture;import com.mojang.datafixers.util.Either;
@Mod.EventBusSubscriber(modid=GeneratedMod.MOD_ID)
public final class DivineSurvey {
 private static final TagKey<Block> ORES=TagKey.create(Registries.BLOCK,new ResourceLocation("forge","ores"));
 private static final TicketType<UUID> TICKET=TicketType.create("myriad_divine_survey",Comparator.<UUID>naturalOrder());
 private static final Map<UUID,Job> JOBS=new HashMap<>();
 private static final class Job {
  final ServerLevel level;final UUID owner;final int minX,minZ;final ArrayDeque<ChunkPos> queue=new ArrayDeque<>();final Set<String> structures=new HashSet<>();final LinkedHashSet<ChunkPos> references=new LinkedHashSet<>();boolean referenceOnly;
  ChunkPos ticket;CompletableFuture<Either<ChunkAccess,ChunkHolder.ChunkLoadingFailure>> future;ChunkAccess chunk;int section,completed;long finishedAt;
  final Map<BlockPos,BlockState> ores=new HashMap<>();
  Job(ServerPlayer p){level=p.serverLevel();owner=p.getUUID();minX=SurveyRules.minimumChunk(p.chunkPosition().x);minZ=SurveyRules.minimumChunk(p.chunkPosition().z);for(int z=0;z<8;z++)for(int x=0;x<8;x++)queue.add(new ChunkPos(minX+x,minZ+z));}
  void release(){if(ticket!=null)level.getChunkSource().removeRegionTicket(TICKET,ticket,0,owner);ticket=null;future=null;chunk=null;ores.clear();}
 }
 public static boolean active(ServerPlayer p){return JOBS.containsKey(p.getUUID());}
 public static boolean eligible(ServerPlayer p){var d=GeneratedMod.data(p);return p.isAlive()&&!p.isSpectator()&&!cn.blockforge.generated.generatedmod.ParalysisControl.blocked(p)&&!GeneratedMod.isSoulProjection(p)&&d!=null&&SurveyRules.unlocked(d.wuxingxiantu$getRealm(),PlayerCrafts.get(p.server).account(p.getUUID()).getBoolean("SenseOpen"));}
 private static boolean pay(ServerPlayer p,int cost){var d=GeneratedMod.data(p);if(d==null)return false;var state=PlayerCrafts.get(p.server);var n=state.account(p.getUUID());float raw=n.getFloat("Sense");float power=Float.isFinite(raw)?Math.max(0,Math.min(SpiritualSense.capacity(d.wuxingxiantu$getRealm()),raw)):0;if(power<cost)return false;n.putFloat("Sense",power-cost);state.setDirty();SpiritualSense.sync(p);return true;}
 public static void toggle(ServerPlayer p){Job old=JOBS.remove(p.getUUID());if(old!=null){old.release();send(p,old,0,List.of());return;}if(SpiritualSense.channeling(p)){p.displayClientMessage(Component.literal("正在凝神，请先完成当前动作。"),true);return;}if(!eligible(p)){p.displayClientMessage(Component.literal("化神期且开辟识海后可探查矿物与结构。"),true);return;}if(!pay(p,SurveyRules.START_COST)){p.displayClientMessage(Component.literal("矿物与结构探查需要8点神识。"),true);return;}Job job=new Job(p);JOBS.put(p.getUUID(),job);send(p,job,1,List.of());p.displayClientMessage(Component.literal("矿物与结构探查：分批扫描8×8区块；每秒消耗1点神识。"),true);}
 private static void stop(ServerPlayer p,Job job){JOBS.remove(p.getUUID());job.release();send(p,job,0,List.of());}

 private static void send(ServerPlayer p,Job j,int mode,List<SurveyPacket.Target> ts){for(int i=0;i<Math.max(1,ts.size());i+=512)Network.CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new SurveyPacket(j.level.dimension().location().toString(),mode,j.completed,ts.subList(i,Math.min(i+512,ts.size()))));}
 private static boolean withinBorder(ServerLevel level,ChunkPos pos){return level.getWorldBorder().isWithinBounds(new BlockPos(pos.getMinBlockX(),0,pos.getMinBlockZ()))&&level.getWorldBorder().isWithinBounds(new BlockPos(pos.getMaxBlockX(),0,pos.getMaxBlockZ()));}
 private static boolean ore(BlockState s){var id=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(s.getBlock());return s.is(ORES)||SurveyRules.spiritOre(s)||(id!=null&&id.getPath().endsWith("_ore"))||s.is(Blocks.ANCIENT_DEBRIS);}
 @SubscribeEvent public static void tick(TickEvent.PlayerTickEvent event){if(event.phase!=TickEvent.Phase.END||!(event.player instanceof ServerPlayer p))return;Job job=JOBS.get(p.getUUID());if(job==null)return;
  if(p.serverLevel()!=job.level||!eligible(p)){stop(p,job);return;}
  if(p.tickCount%20==0&&!pay(p,SurveyRules.UPKEEP_COST)){stop(p,job);p.displayClientMessage(Component.literal("神识不足，已收回矿物与结构探查。"),true);return;}
  if(Math.abs(p.chunkPosition().x-(job.minX+4))>=2||Math.abs(p.chunkPosition().z-(job.minZ+4))>=2){job.release();job=new Job(p);JOBS.put(p.getUUID(),job);send(p,job,1,List.of());}
  if(job.chunk==null){if(job.future==null){if(job.queue.isEmpty()&&job.references.isEmpty()){if(job.finishedAt==0){job.finishedAt=job.level.getGameTime();p.displayClientMessage(Component.literal("神识探查完成：64区块。矿物每30秒复查。"),true);}else if(job.level.getGameTime()-job.finishedAt>=600){if(!pay(p,SurveyRules.START_COST)){stop(p,job);return;}job.release();job=new Job(p);JOBS.put(p.getUUID(),job);send(p,job,1,List.of());}return;}job.referenceOnly=job.queue.isEmpty();if(job.referenceOnly){job.ticket=job.references.iterator().next();job.references.remove(job.ticket);}else job.ticket=job.queue.poll();if(!withinBorder(job.level,job.ticket)){if(!job.referenceOnly)job.completed++;job.ticket=null;return;}job.level.getChunkSource().addRegionTicket(TICKET,job.ticket,0,job.owner);job.future=job.level.getChunkSource().getChunkFuture(job.ticket.x,job.ticket.z,ChunkStatus.FULL,true);return;}if(!job.future.isDone())return;if(job.future.isCompletedExceptionally()){job.release();JOBS.remove(p.getUUID());send(p,job,0,List.of());p.displayClientMessage(Component.literal("神识区块加载失败，请稍后重试"),true);return;}job.chunk=job.future.join().left().orElse(null);if(job.chunk==null){if(job.referenceOnly)job.references.add(job.ticket);else job.queue.addLast(job.ticket);job.release();return;}job.section=job.referenceOnly?job.chunk.getSections().length:0;}
  // At most two non-empty ore-bearing sections per server tick; no synchronous world generation.
  int budget=2;var sections=job.chunk.getSections();while(job.section<sections.length&&budget>0){int index=job.section++;var section=sections[index];if(section.hasOnlyAir()||!section.maybeHas(DivineSurvey::ore))continue;budget--;int by=job.chunk.getMinBuildHeight()+index*16;for(int y=0;y<16;y++)for(int z=0;z<16;z++)for(int x=0;x<16;x++){var s=section.getBlockState(x,y,z);if(ore(s))job.ores.put(new BlockPos(job.ticket.getMinBlockX()+x,by+y,job.ticket.getMinBlockZ()+z),s);}}
  if(job.section>=sections.length){List<SurveyPacket.Target> targets=groups(job.ores);
   if(!job.referenceOnly)for(var refs:job.chunk.getAllReferences().values())for(long ref:refs){ChunkPos at=new ChunkPos(ref);if(!SurveyRules.containsChunk(job.minX,job.minZ,at.x,at.z)&&withinBorder(job.level,at))job.references.add(at);}
   for(var entry:job.chunk.getAllStarts().entrySet()){var start=entry.getValue();if(!start.isValid())continue;var b=start.getBoundingBox();if(b.maxX()<job.minX*16||b.minX()>=(job.minX+8)*16||b.maxZ()<job.minZ*16||b.minZ()>=(job.minZ+8)*16)continue;var id=job.level.registryAccess().registryOrThrow(Registries.STRUCTURE).getKey(entry.getKey());if(id==null)continue;String key=id+":"+start.getChunkPos().toLong();if(job.structures.add(key)){var c=b.getCenter();targets.add(new SurveyPacket.Target(c.getX(),c.getY(),c.getZ(),c.getX()+1,c.getY()+1,c.getZ()+1,"结构 · "+id,0xFFFFCC44,1));}}
   if(!job.referenceOnly)job.completed++;send(p,job,2,targets);job.release();}
 }
 public static List<SurveyPacket.Target> groups(Map<BlockPos,BlockState> source){List<SurveyPacket.Target> out=new ArrayList<>();while(!source.isEmpty()){var first=source.entrySet().iterator().next();BlockPos root=first.getKey();BlockState state=first.getValue();source.remove(root);ArrayDeque<BlockPos> todo=new ArrayDeque<>();todo.add(root);int minX=root.getX(),maxX=minX,minY=root.getY(),maxY=minY,minZ=root.getZ(),maxZ=minZ,count=0;while(!todo.isEmpty()){var p=todo.poll();count++;minX=Math.min(minX,p.getX());maxX=Math.max(maxX,p.getX());minY=Math.min(minY,p.getY());maxY=Math.max(maxY,p.getY());minZ=Math.min(minZ,p.getZ());maxZ=Math.max(maxZ,p.getZ());for(var dir:Direction.values()){var n=p.relative(dir);var found=source.get(n);if(found!=null&&found.getBlock()==state.getBlock()){source.remove(n);todo.add(n);}}}boolean gold=SurveyRules.spiritOre(state);out.add(new SurveyPacket.Target(minX,minY,minZ,maxX+1,maxY+1,maxZ+1,state.getBlock().getDescriptionId()+"|"+count,gold?0xFFFFCC44:0xFF55AAFF,0));}return out;}
 @SubscribeEvent public static void dimension(PlayerEvent.PlayerChangedDimensionEvent e){Job j=JOBS.remove(e.getEntity().getUUID());if(j!=null){j.release();if(e.getEntity() instanceof ServerPlayer p)send(p,j,0,List.of());}}
 @SubscribeEvent public static void stopped(net.minecraftforge.event.server.ServerStoppedEvent e){for(Job j:JOBS.values())j.release();JOBS.clear();}
 @SubscribeEvent public static void clone(PlayerEvent.Clone e){Job j=JOBS.remove(e.getEntity().getUUID());if(j!=null)j.release();}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent e){Job j=JOBS.remove(e.getEntity().getUUID());if(j!=null)j.release();}
}
